import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
import 'app_config.dart';
import 'live_dashboard.dart';
import 'update_checker.dart';
import 'update_launcher.dart';

void main()=>runApp(const AnviMitraApp());
class AnviMitraApp extends StatelessWidget{const AnviMitraApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:AppConfig.appName,debugShowCheckedModeBanner:false,theme:ThemeData(colorSchemeSeed:Colors.indigo,useMaterial3:true),home:const LoginPage());}
class LoginPage extends StatefulWidget{const LoginPage({super.key});@override State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final school=TextEditingController(),login=TextEditingController(),password=TextEditingController();bool busy=false;String? error;Future<void> submit()async{setState(()=>busy=true);try{final r=await http.post(Uri.parse('${AppConfig.apiBaseUrl}/api/auth/login'),headers:{'Content-Type':'application/json'},body:jsonEncode({'schoolCode':school.text.trim(),'login':login.text.trim(),'password':password.text}));final d=jsonDecode(r.body) as Map<String,dynamic>;if(r.statusCode<200||r.statusCode>=300)throw Exception(d['error']??'Login failed');final p=await SharedPreferences.getInstance();await p.setString('accessToken',d['accessToken']);await p.setString('user',jsonEncode(d['user']));if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomePage(user:Map<String,dynamic>.from(d['user']))));}catch(e){setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.school,size:70),const SizedBox(height:12),Text('Anvi Mitra School App',textAlign:TextAlign.center,style:TextStyle(fontSize:25,fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('One app • Every role • One school',textAlign:TextAlign.center),const SizedBox(height:28),TextField(controller:school,decoration:const InputDecoration(labelText:'School Code',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:login,decoration:const InputDecoration(labelText:'Email / Phone',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password',border:OutlineInputBorder())),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error))),const SizedBox(height:18),FilledButton(onPressed:busy?null:submit,child:Padding(padding:const EdgeInsets.all(13),child:Text(busy?'Signing in…':'Sign in')))]))))));}}
class HomePage extends StatefulWidget{final Map<String,dynamic> user;const HomePage({super.key,required this.user});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{AppUpdateInfo? update;@override void initState(){super.initState();_check();}Future<void> _check()async{final u=await UpdateChecker().check();if(mounted&&u!=null&&(u.available||u.required)){setState(()=>update=u);if(u.required)WidgetsBinding.instance.addPostFrameCallback((_){showDialog(context:context,barrierDismissible:false,builder:(_)=>AlertDialog(title:const Text('Update Required'),content:Text('Please update to version ${u.latestVersion??'latest'} to continue.'),actions:[FilledButton(onPressed:()=>UpdateLauncher.open(u.updateUrl),child:const Text('Update Now'))]));});}}@override Widget build(BuildContext c){final role=(widget.user['role']??'').toString().toLowerCase();return Scaffold(appBar:AppBar(title:Text(widget.user['schoolName']??AppConfig.appName),actions:[IconButton(onPressed:()=>_logout(),icon:const Icon(Icons.logout))]),body:Column(children:[if(update!=null&&!update!.required)MaterialBanner(content:Text('New version ${update!.latestVersion??''} available'),leading:const Icon(Icons.system_update),actions:[TextButton(onPressed:()=>UpdateLauncher.open(update!.updateUrl),child:const Text('UPDATE'))]),Expanded(child:LiveDashboard(role:role))]));}Future<void> _logout()async{final p=await SharedPreferences.getInstance();await p.clear();if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const LoginPage()),(_)=>false);}}
